    @property
    def notifier(self):
        if self._notifier is None:
            from .notifier.client import AsyncNotifierClient  # noqa: E402

            self._notifier = AsyncNotifierClient(client_wrapper=self._client_wrapper)
        return self._notifier

    @property
    def schedule(self):
        if self._schedule is None:
            from .schedule.client import AsyncScheduleClient  # noqa: E402

            self._schedule = AsyncScheduleClient(client_wrapper=self._client_wrapper)
        return self._schedule

    @property
    def version(self):
        if self._version is None:
            from .version.client import AsyncVersionClient  # noqa: E402

            self._version = AsyncVersionClient(client_wrapper=self._client_wrapper)
        return self._version
